/* Corresponds to libjpeg 6b jcparam.c fill_a_scan (open-source IJG libjpeg 6b). Generated by km/libmatch.py: the upstream function with the declarations it uses, preprocessed, symbols renamed to the game's. */
typedef struct {
  int comps_in_scan;
  int component_index[4];
  int Ss, Se;
  int Ah, Al;
} jpeg_scan_info;

jpeg_scan_info *
fill_a_scan (jpeg_scan_info * scanptr, int ci,
	     int Ss, int Se, int Ah, int Al)

{
  scanptr->comps_in_scan = 1;
  scanptr->component_index[0] = ci;
  scanptr->Ss = Ss;
  scanptr->Se = Se;
  scanptr->Ah = Ah;
  scanptr->Al = Al;
  scanptr++;
  return scanptr;
}
